int parse_file_permission(const char* perm_str, char* filename, size_t filename_size, char* permission, size_t perm_size) {
    if (!perm_str || !filename || !permission || filename_size == 0 || perm_size == 0) {
        return -1; // Invalid input parameters
    }

    // Find the position of the colon separator
    const char* colon_pos = strchr(perm_str, ':');
    if (!colon_pos) {
        return -1; // No colon found, invalid format
    }

    // Calculate lengths
    size_t total_len = strlen(perm_str);
    size_t filename_len = colon_pos - perm_str;
    size_t permission_len = total_len - filename_len - 1; // -1 for the colon

    // Check if the buffers are large enough
    if (filename_len >= filename_size || permission_len >= perm_size) {
        return -1; // Buffer too small
    }

    // Copy filename part
    strncpy(filename, perm_str, filename_len);
    filename[filename_len] = '\0';

    // Copy permission part
    strcpy(permission, colon_pos + 1);

    return 0; // Success
}
